public int kruskalNaive(int n, int[][] edges) {
    Arrays.sort(edges, (a, b) -> Integer.compare(a[2], b[2]));
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    long total = 0;
    int picked = 0;
    for (int[] e : edges) {
        int ru = find(parent, e[0]), rv = find(parent, e[1]);
        if (ru != rv) {
            parent[ru] = rv;          // naive union, no rank
            total += e[2];
            picked++;
        }
    }
    return picked == n - 1 ? (int) total : -1;
}

private int find(int[] parent, int x) {
    while (parent[x] != x) x = parent[x];   // no path compression
    return x;
}

public int kruskal(int n, int[][] edges) {
    Arrays.sort(edges, (a, b) -> Integer.compare(a[2], b[2]));
    int[] parent = new int[n];
    int[] rank = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;

    long total = 0;
    int picked = 0;
    for (int[] e : edges) {
        if (union(parent, rank, e[0], e[1])) {
            total += e[2];
            if (++picked == n - 1) break;
        }
    }
    return picked == n - 1 ? (int) total : -1;
}

private int find(int[] parent, int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != root) {        // path compression (iterative)
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

private boolean union(int[] parent, int[] rank, int a, int b) {
    int ra = find(parent, a), rb = find(parent, b);
    if (ra == rb) return false;        // already connected → cycle
    if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
    parent[rb] = ra;                   // attach shorter under taller
    if (rank[ra] == rank[rb]) rank[ra]++;
    return true;
}

code.python:
def kruskal(self, n: int, edges: list[list[int]]) -> int:
    edges.sort(key=lambda e: e[2])
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:        # path compression (iterative)
            parent[x], x = root, parent[x]
        return root

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False                # already connected → cycle
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra                 # attach shorter under taller
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    total = 0
    picked = 0
    for u, v, w in edges:
        if union(u, v):
            total += w
            picked += 1
            if picked == n - 1:
                break
    return total if picked == n - 1 else -1

